1553	        ErrorCodes.NOT_INITIALIZED.exitCode,
1554	      );
1555	    }
1556	
1557	    const lowerName = name.toLowerCase();
1558	
1559	    // Reject reserved name
1560	    if (lowerName === "anonymous") {
1561	      return {
1562	        result: "USER_ALREADY_EXISTS",
1563	        message: `"anonymous" is a reserved name and cannot be registered.`,
1564	      };
1565	    }
1566	
1567	    const users = await readJSON<UsersFile>(join(trackerDir, "users.json"));
1568	
1569	    // Check uniqueness
1570	    if (users.users.find((u) => u.name === lowerName)) {
1571	      return {
1572	        result: "USER_ALREADY_EXISTS",
1573	        message: `User "${lowerName}" already exists.`,
1574	      };
1575	    }
1576	
1577	    const token = generateToken();
1578	    const newUser: UserEntry = {
1579	      name: lowerName,
1580	      token,
1581	      registeredAt: new Date().toISOString(),
1582	    };
1583	
1584	    users.users.push(newUser);
1585	    await atomicWriteJSON(join(trackerDir, "users.json"), users);
