      );
    }

    const config = await readJSON<ConfigFile>(join(trackerDir, "config.json"));
    const users = await readJSON<UsersFile>(join(trackerDir, "users.json"));
    const authResult = resolveAuthor({ config, users, requiresWrite: true });
